MM.mnemo[2] = {"cards":[{"id":"ko-k3-0040","w":"쇼핑하다","cs":"nakupovat, jít nakupovat","en":"to shop, to go shopping","p":"v","o":"e","ex":"내일 영화를 보고, 쇼핑하러 갈 거예요.","exc":"Zítra se podívám na film a půjdu nakupovat. (를 → 4. pád; -러 가다 → jít za účelem)","m":"Z angl. shopping + 하다; označuje hlavně nakupování oblečení a věcí pro radost. Pro běžný nákup potravin a věcí do domácnosti korejština používá spojení 장을 보다.","tv":["쇼핑해요"]},{"id":"ko-k3-0041","w":"수영하다","cs":"plavat","en":"to swim","p":"v","o":"m","ex":"수영하고, 영어 공부하고, 점심 먹었어요.","exc":"Zaplaval jsem si, učil se anglicky a naobědval se. (-고 → a)","m":"水 voda + 泳 plavat (+ 하다) = pohybovat se ve vodě, plavat. Ryze korejsky se plavání řekne 헤엄치다. Kořen 水 najdeš i ve slovech 수박 (vodní meloun) nebo 생수 (balená voda).","r":["su-水","yeong-泳"],"tv":["수영해요"]},{"id":"ko-k3-0042","w":"씻다","cs":"umýt se, mýt (se)","en":"to wash (oneself)","p":"v","o":"k","ex":"집에 가서 씻고 잤어요.","exc":"Přišel jsem domů, umyl se a šel spát. (에 → kam; -아서 → a pak; -고 → a)","m":"Označuje mytí těla, rukou, obličeje nebo nádobí (손을 씻다 = umýt si ruce). Na praní prádla se používá 빨래하다 a na mytí vlasů 감다 (머리를 감다).","tv":["씻어요"]},{"id":"ko-k3-0044","w":"배부르다","cs":"sytý, najedený","en":"to be full (after eating)","p":"a","o":"k","ex":"지금 배가 너무 불러요.","exc":"Teď jsem úplně plný. (가 → 1. pád; 너무 → moc, příliš)","m":"Doslova ‚břicho (배) je plné (부르다)‘ – často se rozděluje na 배가 부르다. Pozor na nepravidelné časování 르: 배부르다 → 배불러요. Opakem je 배고프다 (mít hlad).","tv":["배불러요"],"irr":"르"},{"id":"ko-k3-0047","w":"서점","cs":"knihkupectví","en":"bookstore","p":"n","o":"s","ex":"서점에 갈 거예요.","exc":"Půjdu do knihkupectví. (에 → kam)","m":"書 kniha + 店 obchod = obchod s knihami, tedy knihkupectví. Kořen 書 najdeš i ve slově 도서관 (knihovna).","r":["seo-書","jeom-店"]},{"id":"ko-k3-0054","w":"도너츠","cs":"kobliha, donut","en":"donut","p":"n","o":"e","ex":"커피 마시고, 도너츠 먹었어요.","exc":"Dal jsem si kávu a snědl koblihu. (-고 → a)","m":"Výpůjčka z anglického ‚doughnuts‘ (množné číslo). V běžné řeči se často používá tento tvar 도너츠, spisovný pravopis je dnes 도넛."},{"id":"ko-k3-0055","w":"케이크","cs":"dort, koláč","en":"cake","p":"n","o":"e","ex":"케이크 먹고, 우유 마셨어요.","exc":"Snědl jsem dort a zapil ho mlékem. (-고 → a)","m":"Výpůjčka z anglického ‚cake‘. V mluvené korejštině se často zkracuje na 케익; jeden kousek dortu se řekne 조각 케이크."},{"id":"ko-k3-0057","w":"배","cs":"břicho, žaludek","en":"stomach, belly","p":"n","o":"k","ex":"지금 배가 너무 불러요.","exc":"Teď mám úplně plné břicho. (가 → 1. pád; 너무 → moc, příliš)","m":"Slovo 배 má v korejštině tři úplně odlišné významy: břicho, hruška a loď – vždy rozhoduje kontext. Častá spojení: 배가 고프다 (mít hlad) a 배가 부르다 (být sytý)."},{"id":"ko-k3-0059","w":"냉장고","cs":"lednička, chladnička","en":"fridge","p":"n","o":"s","ex":"냉장고가 시끄럽고 따뜻해요.","exc":"Lednička je hlučná a teplá. (가 → 1. pád; -고 → a)","m":"冷 studený + 藏 ukládat + 庫 sklad = chladný sklad na potraviny, tedy lednička. Stejné 冷 najdeš i ve slově 냉면 (studené nudle).","r":["naeng-冷","jang-藏","go-庫"]},{"id":"ko-k3-0060","w":"따뜻하다","cs":"teplý","en":"to be warm","p":"a","o":"k","ex":"냉장고가 시끄럽고 따뜻해요.","exc":"Lednička je hlučná a teplá. (가 → 1. pád; -고 → a)","m":"Příjemně teplý (o počasí, nápoji nebo pocitu), na rozdíl od 덥다 (horko o počasí) a 뜨겁다 (horký na dotek). Opakem je 춥다 (chladno) nebo 차갑다 (studený)."},{"id":"ko-k3-0061","w":"청소하다","cs":"uklízet, uklidit","en":"to clean","p":"v","o":"m","ex":"오늘 청소하고, 커피 만들었어요.","exc":"Dnes jsem uklidil a udělal si kávu. (-고 → a)","m":"淸 čistý + 掃 zametat (+ 하다) = zamést do čista, tedy uklízet. Kořen 淸 (čistý) najdeš i ve slově 청소기 (vysavač).","r":["cheong-淸","so-掃"],"tv":["청소해요"]},{"id":"ko-k3-0062","w":"출근하다","cs":"jít do práce, přijít do práce","en":"to go/come to work","p":"v","o":"m","ex":"출근하고, 청소했어요.","exc":"Přišel jsem do práce a uklidil. (-고 → a)","m":"出 vyjít + 勤 pracovat, sloužit (+ 하다) = vyrazit do práce / nastoupit do směny. Přímým opakem je 퇴근하다 (odejít z práce domů).","r":["chul-出","geun-勤"]}],"gram":{"id":"ko-k3-g02","w":"-고","en":"Linking Verbs","cs":"a; a pak (spojování sloves a přídavných jmen)","vy":"Koncovka -고 se připojuje přímo ke kmeni slovesa nebo přídavného jména bez ohledu na to, zda končí souhláskou, nebo samohláskou. Spojuje dvě a více vlastností či dějů ve významu ‚a‘ nebo ‚a pak‘. Čas se obvykle vyjadřuje až u posledního slovesa ve větě, ale u ukončených minulých dějů může být minulý čas i před -고.","m":"Na rozdíl od -아서/어서 nevyjadřuje koncovka -고 příčinu ani těsnou návaznost — jen neutrálně řadí děje nebo vlastnosti za sebe jako české ‚a‘ či ‚a pak‘.","s":[["이 책은 재미있고 싸요.","Tahle kniha je zajímavá a levná."],["이 책은 재미있고, 싸고, 좋아요.","Tahle kniha je zajímavá, levná a dobrá."],["어제 친구를 만났고, 영화를 봤어요.","Včera jsem se sešel s kamarádem a dívali jsme se na film."],["내일 영화를 보고, 서점에 갈 거예요.","Zítra se podívám na film a půjdu do knihkupectví."],["내일은 친구 만나고, 서점에 갈 거예요.","Zítra se sejdu s kamarádem a půjdu do knihkupectví."],["책 읽고, 공부하고, 운동했어요.","Četl jsem knihu, učil se a cvičil."],["9월에는 한국에 가고, 10월에는 일본에 갈 거예요.","V září pojedu do Koreje a v říjnu pojedu do Japonska."],["커피 마시고, 도너츠 먹고, 케이크 먹고, 우유 마셨어요. 배불러요.","Dal jsem si kávu, snědl donut, snědl dort a vypil mléko. Jsem plný."],["어제 영화 보고 뭐 했어요?","Co jsi dělal včera poté, co ses podíval na film?"],["밥 먹고 집에 갔어요?","Najedl ses a šel domů?"],["집에 가서 씻고 잤어요.","Šel jsem domů, umyl se a spal."],["수영하고, 영어 공부하고, 점심 먹었어요.","Zaplaval jsem si, učil se angličtinu a naobědval se."],["오늘 청소하고, 커피 만들고, 택배 받았어요.","Dneska jsem uklidil, udělal kávu a převzal balíček."],["냉장고가 시끄럽고 따뜻해요.","Lednička je hlučná a teplá."],["어제도 야근했고, 오늘도 야근해요.","Včera jsem dělal přesčas a dneska dělám přesčas taky."],["우유 마시고 잘 거예요.","Vypiju mléko a půjdu spát."]]}};
